"""Recursively describe an archive/compressed artifact in memory (never loads pickles)."""
import bz2
import gzip
import io
import lzma
import os
import sys
import tarfile
import zipfile


def kind(data):
    if data[:2] == b"\x1f\x8b":
        return "gzip"
    if data[:3] == b"BZh":
        return "bz2"
    if data[:6] == b"\xfd7zXZ\x00":
        return "xz"
    if data[:4] == b"PK\x03\x04":
        return "zip"
    if data[:6] == b"\x93NUMPY":
        return "npy"
    if data[:8] == b"\x89HDF\r\n\x1a\n":
        return "hdf5"
    if len(data) > 262 and data[257:262] == b"ustar":
        return "tar"
    if data[:1] == b"\x80":
        return "pickle"
    return "unknown"


def describe(data, name, depth, dump_dir):
    ind = "  " * depth
    k = kind(data)
    print(f"{ind}{name}: {len(data)} bytes, kind={k}, head={data[:12]!r}")
    if k == "gzip":
        describe(gzip.decompress(data), name + "|gunzip", depth + 1, dump_dir)
    elif k == "bz2":
        describe(bz2.decompress(data), name + "|bunzip2", depth + 1, dump_dir)
    elif k == "xz":
        describe(lzma.decompress(data), name + "|unxz", depth + 1, dump_dir)
    elif k == "zip" or (k == "unknown" and zipfile.is_zipfile(io.BytesIO(data))):
        zf = zipfile.ZipFile(io.BytesIO(data))
        for info in zf.infolist():
            print(f"{ind}  member {info.filename!r} ctype={info.compress_type} size={info.file_size} off={info.header_offset}")
            describe(zf.read(info), name + "!" + info.filename, depth + 2, dump_dir)
    elif k == "tar":
        tf = tarfile.open(fileobj=io.BytesIO(data))
        for m in tf.getmembers():
            print(f"{ind}  tar member {m.name!r} type={m.type!r} size={m.size}")
            if m.isfile():
                describe(tf.extractfile(m).read(), name + "!" + m.name, depth + 2, dump_dir)
    else:
        if dump_dir:
            out = os.path.join(dump_dir, name.replace("/", "_").replace("|", "_").replace("!", "__"))
            with open(out, "wb") as f:
                f.write(data)
            print(f"{ind}  -> dumped to {out}")


if __name__ == "__main__":
    p = sys.argv[1]
    dump = sys.argv[2] if len(sys.argv) > 2 else None
    if dump:
        os.makedirs(dump, exist_ok=True)
    describe(open(p, "rb").read(), os.path.basename(p), 0, dump)

