    """``obj.method``: ``func`` is called with ``obj`` prepended."""

    __slots__ = ("obj", "func")

    def __init__(self, obj, func):
        self.obj = obj
        self.func = func

    def describe(self):
        return f"{describe(self.func)} bound to {describe(self.obj)}"


