    if name.startswith("."):
        pkg = _arg(args, kwargs, 1, "package")
        if not isinstance(pkg, str):
            raise PickleStop("relative import requires a package")
        name = pkg + name
        name = name.replace("..", ".")
    return rt.import_module(name, site)


