    key = kwargs.get("key")
    if key is not None:
        for x in items:
            rt.call(key, (x,), {}, site, how + " key ->")
    if not items:
        if "default" in kwargs:
            return kwargs["default"]
        raise PickleStop("min/max arg is an empty sequence")
    if len(items) == 1:
