@handler("os.path.join")
def h_path_join(rt, args, kwargs, site, how):
    if args and all(isinstance(a, str) for a in args):
        import posixpath
        return posixpath.join(*args)
    return Opaque("path")


@handler("re.sub", "re.subn")
def h_re_sub(rt, args, kwargs, site, how):
    return Opaque("text")


@handler("string.Template")
def h_template(rt, args, kwargs, site, how):
    return Inst(rt.glob("string.Template", "class"), args, kwargs)


@handler("importlib.util.find_spec", "importlib.util.resolve_name")
def h_spec(rt, args, kwargs, site, how):
    return Opaque("module spec")
