def _arg(args, kwargs, i, kw, default=None):
    if len(args) > i:
        return args[i]
    return kwargs.get(kw, default)


def _need_str(v, what):
    if not isinstance(v, str):
        raise PickleStop(f"{what} must be a string, not {describe(v)}")
    return v


