        if not d.eof:
            raise PickleStop("incomplete or truncated zlib stream")
        return out
    if kind == "bz2":
        out = bytearray()
        rest = data
        while rest:
            d = bz2.BZ2Decompressor()
            out += d.decompress(rest, limit + 1 - len(out))
            if len(out) > limit:
                raise PickleStop("decompressed data too large")
            if not d.eof:
                raise PickleStop("truncated bz2 stream")
            rest = d.unused_data
        return bytes(out)
    if kind in ("lzma", "xz"):
        out = bytearray()
        rest = data
        while rest:
            d = lzma.LZMADecompressor()
            out += d.decompress(rest, limit + 1 - len(out))
            if len(out) > limit:
                raise PickleStop("decompressed data too large")
            if not d.eof:
                raise PickleStop("truncated lzma stream")
            rest = d.unused_data
            if rest and not rest.startswith((b"\xfd7zXZ", b"]\x00\x00")):
                break
        return bytes(out)
    if kind == "gzip":
        out = bytearray()
        rest = data
        while rest:
            if rest[:2] != b"\x1f\x8b":
