    u.marks.append(len(u.stack))


@op(".")
def op_stop(u):
    u.result = u.pop()
    return STOP_MARK


@op("0")
def op_pop(u):
    if u.marks and u.marks[-1] == len(u.stack):
        u.marks.pop()
