def _make_dict(u, items):
    if len(items) % 2:
        raise PickleStop("odd number of items for DICT")
    d = {}
    for i in range(0, len(items), 2):
        u.rt.hashable(items[i])
        d[items[i]] = items[i + 1]
    return d


