    m = u.marker()
    if m < 1 or m - 1 < (u.marks[-1] if u.marks else 0):
        raise PickleStop("unpickling stack underflow")
    items = u.stack[m:]
    del u.stack[m:]
    if items:
        u.rt.additems(u.stack[m - 1], items, u.site)


