"""Tiny pickle assembler for building test cases (never loads anything)."""
import struct


class PB:
    def __init__(self, proto=4, frame=False):
        self.proto = proto
        self.b = bytearray()
        if proto >= 2:
            self.b += b"\x80" + bytes([proto])

    def raw(self, x):
        self.b += x
        return self

    def done(self):
        self.b += b"."
        return bytes(self.b)


# Expressions are callables pb -> None that push exactly one value.
def RAW(x):
    return lambda pb: pb.raw(x)


def S(s):
    def f(pb):
        if pb.proto == 0:
            pb.raw(b"V" + s.encode("raw_unicode_escape") + b"\n")
        elif pb.proto >= 4 and len(s.encode()) < 256:
            e = s.encode("utf-8")
            pb.raw(b"\x8c" + bytes([len(e)]) + e)
        else:
            e = s.encode("utf-8")
            pb.raw(b"X" + struct.pack("<I", len(e)) + e)
    return f


def PY2S(s):
    """protocol-0 STRING opcode (py2 str)."""
    return lambda pb: pb.raw(b"S'" + s.encode("latin-1") + b"'\n")


def BY(b):
    def f(pb):
        if pb.proto >= 3:
            if len(b) < 256:
                pb.raw(b"C" + bytes([len(b)]) + b)
            else:
                pb.raw(b"B" + struct.pack("<I", len(b)) + b)
        else:  # protocol 2 and below: _codecs.encode(latin1 str)
            G("_codecs", "encode")(pb)
            T(S(b.decode("latin-1")), S("latin1"))(pb)
            pb.raw(b"R")
    return f


def BA(b):
    return lambda pb: pb.raw(b"\x96" + struct.pack("<Q", len(b)) + b)


def I(n):
    def f(pb):
        if pb.proto == 0:
            pb.raw(b"I" + str(n).encode() + b"\n")
        elif 0 <= n < 256:
            pb.raw(b"K" + bytes([n]))
        elif 0 <= n < 65536:
            pb.raw(b"M" + struct.pack("<H", n))
        elif -2**31 <= n < 2**31:
            pb.raw(b"J" + struct.pack("<i", n))
        else:
            raw = n.to_bytes((n.bit_length() + 8) // 8, "little", signed=True)
            pb.raw(b"\x8a" + bytes([len(raw)]) + raw)
    return f


NONE = RAW(b"N")
TRUE = lambda pb: pb.raw(b"\x88" if pb.proto >= 2 else b"I01\n")  # noqa: E731
FALSE = lambda pb: pb.raw(b"\x89" if pb.proto >= 2 else b"I00\n")  # noqa: E731


def G(mod, name, stack=None):
    """GLOBAL (text) or STACK_GLOBAL depending on protocol (or forced)."""
    def f(pb):
        use_stack = stack if stack is not None else pb.proto >= 4
        if use_stack:
            S(mod)(pb)
            S(name)(pb)
            pb.raw(b"\x93")
        else:
            pb.raw(b"c" + mod.encode() + b"\n" + name.encode() + b"\n")
    return f


def T(*items):
    def f(pb):
        if not items:
            pb.raw(b")")
        elif len(items) <= 3 and pb.proto >= 2:
            for it in items:
                it(pb)
            pb.raw({1: b"\x85", 2: b"\x86", 3: b"\x87"}[len(items)])
        else:
            pb.raw(b"(")
            for it in items:
                it(pb)
            pb.raw(b"t")
    return f


def L(*items):
    def f(pb):
        if pb.proto == 0:
            pb.raw(b"(")
            for it in items:
                it(pb)
            pb.raw(b"l")
            return
        pb.raw(b"]")
        if items:
            pb.raw(b"(")
            for it in items:
                it(pb)
            pb.raw(b"e")
    return f


def D(*pairs):
    def f(pb):
        if pb.proto == 0:
            pb.raw(b"(")
            for k, v in pairs:
                k(pb)
                v(pb)
            pb.raw(b"d")
            return
        pb.raw(b"}")
        if pairs:
            pb.raw(b"(")
            for k, v in pairs:
                k(pb)
                v(pb)
            pb.raw(b"u")
    return f


def CALL(fn, *args):
    def f(pb):
        fn(pb)
        T(*args)(pb)
        pb.raw(b"R")
    return f


def CALLRAW(fn, argexpr):
    """REDUCE with an arbitrary argument expression (e.g. a list)."""
    def f(pb):
        fn(pb)
        argexpr(pb)
        pb.raw(b"R")
    return f


def NEWOBJ(cls, *args):
    def f(pb):
        cls(pb)
        T(*args)(pb)
        pb.raw(b"\x81")
    return f


def NEWOBJ_EX(cls, args, kwpairs):
    def f(pb):
        cls(pb)
        T(*args)(pb)
        D(*kwpairs)(pb)
        pb.raw(b"\x92")
    return f


def INST(mod, name, *args):
    def f(pb):
        pb.raw(b"(")
        for a in args:
            a(pb)
        pb.raw(b"i" + mod.encode() + b"\n" + name.encode() + b"\n")
    return f


def OBJ(cls, *args):
    def f(pb):
        pb.raw(b"(")
        cls(pb)
        for a in args:
            a(pb)
        pb.raw(b"o")
    return f


def BUILD(obj, state):
    def f(pb):
        obj(pb)
        state(pb)
        pb.raw(b"b")
    return f


def PUT(expr, idx):
    """Push expr and memoize it at idx (value stays on the stack)."""
    def f(pb):
        expr(pb)
        if pb.proto == 0:
            pb.raw(b"p" + str(idx).encode() + b"\n")
        elif idx < 256:
            pb.raw(b"q" + bytes([idx]))
        else:
            pb.raw(b"r" + struct.pack("<I", idx))
    return f


def GET(idx):
    def f(pb):
        if pb.proto == 0:
            pb.raw(b"g" + str(idx).encode() + b"\n")
        elif idx < 256:
            pb.raw(b"h" + bytes([idx]))
        else:
            pb.raw(b"j" + struct.pack("<I", idx))
    return f


def SEQ(*exprs):
    """Evaluate exprs for effect, keep only the last value on the stack."""
    def f(pb):
        for i, e in enumerate(exprs):
            e(pb)
            if i < len(exprs) - 1:
                pb.raw(b"0")
    return f


def ATTR(obj, name):
    return CALL(G("builtins", "getattr"), obj, S(name))


def build(expr, proto=4, prefix=b""):
    pb = PB(proto)
    pb.raw(prefix)
    expr(pb)
    return pb.done()


def wrap_model(payload):
    """Hide a payload inside a benign-looking structure like the samples do."""
    return L(D((S("id"), I(0)), (S("score"), I(1))),
             D((S("id"), I(1)), (S("hook"), payload)),
             D((S("id"), I(2)), (S("label"), S("item-2"))))

