def rglob():
    n = random.choice(names)
    mod, _, attr = n.rpartition('.')
    if random.random() < 0.3 and '.' in mod:
        m2, _, a2 = mod.rpartition('.')
        return G(m2, a2 + '.' + attr)
    return G(mod, attr)


def rval(depth=0):
    r = random.random()
    if depth > 3 or r < 0.3:
        return random.choice([S('x'), S('os'), S('system'), S('os:system'), I(random.randint(-3, 300)), NONE, TRUE,
                              BY(b'\x80\x02K\x01.'), BY(b'abc'), S('pickle'), S(''), S('__dict__'), S('0')])
    if r < 0.45:
        return L(*[rval(depth + 1) for _ in range(random.randint(0, 3))])
    if r < 0.55:
        return T(*[rval(depth + 1) for _ in range(random.randint(0, 3))])
    if r < 0.6:
        return D(*[(S(random.choice('abc')), rval(depth + 1)) for _ in range(random.randint(0, 2))])
    if r < 0.8:
        return CALL(rglob(), *[rval(depth + 1) for _ in range(random.randint(0, 3))])
    if r < 0.85:
        return NEWOBJ(rglob(), *[rval(depth + 1) for _ in range(random.randint(0, 2))])
    if r < 0.9:
        return BUILD(rval(depth + 1), rval(depth + 1))
    if r < 0.95:
        return rglob()
    return CALL(CALL(rglob(), rval(depth + 1)), rval(depth + 1))


errors = {}
t0 = time.time()
n = int(sys.argv[1])
for i in range(n):
    expr = L(*[rval() for _ in range(random.randint(1, 4))])
    try:
        data = build(expr, random.choice([2, 4]))
    except Exception:
        continue
    ctx = Context(time.monotonic() + 10)
    try:
        loaders.scan_blob(ctx, data, 'g', 'g.pkl', 0, top=True)
    except (ScanAbort, PickleStop):
        pass
    except Exception as exc:
        tb = traceback.format_exc()
        key = type(exc).__name__ + ':' + tb.strip().splitlines()[-3].strip()
        if key not in errors:
            errors[key] = tb
            open(f'/tmp/work/gerr_{len(errors)}.pkl', 'wb').write(data)
            print('NEWERR', len(errors), key, flush=True)
            print(tb[-900:], flush=True)
print('runs', n, 'secs', round(time.time() - t0, 1), 'errors', len(errors))
