import importlib, inspect, json, re, sys, types, warnings
warnings.simplefilter('ignore')
sys.path.insert(0, '/app')
kb = json.load(open('/app/modelgate/kb_data.json'))
danger = set(kb['danger']) | set(kb['nested'])
canon = kb['canon']
PAT = re.compile(r'\b(os\.system|_os\.system|subprocess\.(Popen|run|call|check_output|check_call|getoutput|getstatusoutput)|'
                 r'os\.(exec\w+|spawn\w+|posix_spawn\w*|popen|fork)\(|\beval\(|\bexec\(|\bcompile\(|'
                 r'socket\.create_connection|\.connect\(|urlopen\(|os\.(remove|unlink|rename|replace|mkdir|makedirs|rmdir)\(|'
                 r'shutil\.(rmtree|copy\w*|move)\(|\bopen\()')
skip_mods = ('test', 'idlelib', 'tkinter', 'turtle', 'lib2to3', 'pydoc_data', 'ensurepip', 'encodings', 'distutils')
seen = set()
rows = []
for modname in kb['known_modules']:
    if modname.split('.')[0] in skip_mods or modname.startswith('numpy'):
        continue
    mod = sys.modules.get(modname)
    if mod is None:
        try:
            mod = importlib.import_module(modname)
        except BaseException:
            continue
    for attr, val in list(vars(mod).items()):
        objs = []
        if isinstance(val, types.FunctionType) and val.__module__ == modname:
            objs.append((f'{modname}.{attr}', val))
        elif isinstance(val, type) and val.__module__ == modname:
            for k, v in list(val.__dict__.items()):
                if isinstance(v, (staticmethod, classmethod)):
                    v = v.__func__
                if isinstance(v, types.FunctionType):
                    objs.append((f'{modname}.{attr}.{k}', v))
        for name, fn in objs:
            if id(fn) in seen:
                continue
            seen.add(id(fn))
            try:
                src = inspect.getsource(fn)
            except Exception:
                continue
            hits = sorted(set(m.group(0) for m in PAT.finditer(src)))
            if hits and name not in danger and canon.get(name, name) not in danger:
                rows.append((name, hits))
for name, hits in rows:
    print(name, hits)
print(len(rows), file=sys.stderr)
