"""Differential fuzzing: scanner emulation vs. the real unpickler, with canary targets.

Random pickles are built from safe real gadgets (getattr, partial, map, ...) and
canary functions (cmod.*, which only print HIT).  Each is loaded by the real
C unpickler in a fresh process; the scanner (with cmod.* registered as
capabilities) must report a finding exactly when a canary fired.
"""
import inspect
import json
import os
import random
import subprocess
import sys
import time

sys.path.insert(0, "/app")
sys.path.insert(0, "/tmp/work/gen")
sys.path.insert(0, "/tmp/work/canary")
sys.setrecursionlimit(20000)
from pasm import *  # noqa: F401,F403,E402
from modelgate import kb as kbmod  # noqa: E402
from modelgate import loaders  # noqa: E402
from modelgate.pickle_vm import Context, ScanAbort  # noqa: E402

import cmod  # noqa: E402

K = kbmod.get()
CANARY_FUNCS = ["system", "eval", "exec", "hit0", "hit1", "hit2", "hitv"]
for name in CANARY_FUNCS + ["Popen"]:
    K.danger_table[f"cmod.{name}"] = ("process", None)
    try:
        sig = inspect.signature(getattr(cmod, name))
        pos, req, var_pos, kwonly, kwreq, var_kw = [], 0, False, [], [], False
        for p in sig.parameters.values():
            if p.kind in (p.POSITIONAL_ONLY, p.POSITIONAL_OR_KEYWORD):
                pos.append(p.name if p.kind == p.POSITIONAL_OR_KEYWORD else None)
                if p.default is p.empty:
                    req = len(pos)
            elif p.kind == p.VAR_POSITIONAL:
                var_pos = True
            elif p.kind == p.KEYWORD_ONLY:
                kwonly.append(p.name)
                if p.default is p.empty:
                    kwreq.append(p.name)
            elif p.kind == p.VAR_KEYWORD:
                var_kw = True
        if name != "Popen":
            K.signatures[f"cmod.{name}"] = [pos, req, var_pos, kwonly, kwreq, var_kw]
    except (TypeError, ValueError):
        pass

random.seed(int(sys.argv[2]) if len(sys.argv) > 2 else 1)
N = int(sys.argv[1]) if len(sys.argv) > 1 else 200
PROTO = [2, 4]

SAFE_CALLABLES = [
    ("builtins", "getattr"), ("builtins", "setattr"), ("builtins", "list"), ("builtins", "tuple"),
    ("builtins", "set"), ("builtins", "dict"), ("builtins", "sorted"), ("builtins", "next"), ("builtins", "iter"),
    ("builtins", "map"), ("builtins", "filter"), ("builtins", "vars"), ("builtins", "str"), ("builtins", "len"),
    ("builtins", "min"), ("builtins", "max"), ("builtins", "any"), ("builtins", "all"), ("builtins", "sum"),
    ("builtins", "enumerate"), ("builtins", "zip"), ("builtins", "reversed"), ("builtins", "frozenset"),
    ("builtins", "type"), ("builtins", "staticmethod"),
    ("functools", "partial"), ("functools", "reduce"), ("functools", "lru_cache"), ("functools", "cache"),
    ("operator", "attrgetter"), ("operator", "methodcaller"), ("operator", "itemgetter"), ("operator", "getitem"),
    ("operator", "setitem"), ("operator", "call"), ("operator", "add"), ("itertools", "starmap"),
    ("itertools", "chain"), ("itertools", "islice"), ("itertools", "accumulate"), ("copy", "copy"),
    ("importlib", "import_module"), ("collections", "OrderedDict"), ("collections", "defaultdict"),
    ("collections", "deque"), ("types", "MethodType"), ("types", "SimpleNamespace"),
]
CANARY_GLOBALS = [("cmod", n) for n in CANARY_FUNCS] + [("cmod", "Popen"), ("cmod", "fspath"), ("cmod", "Plain")]
STRS = ["system", "hit1", "fspath", "cmod", "x", "upper", "__dict__", "join", "append", "Plain", "__setstate__"]


def leaf(depth):
    r = random.random()
    if r < 0.35:
        return S(random.choice(STRS))
    if r < 0.45:
        return I(random.randint(0, 3))
    if r < 0.5:
        return NONE
    if r < 0.8:
        m, n = random.choice(CANARY_GLOBALS)
        return G(m, n)
    m, n = random.choice(SAFE_CALLABLES)
    return G(m, n)


def expr(depth=0):
    if depth > 3:
        return leaf(depth)
    r = random.random()
    if r < 0.3:
        return leaf(depth)
    if r < 0.4:
        return L(*[expr(depth + 1) for _ in range(random.randint(0, 2))])
    if r < 0.5:
        return T(*[expr(depth + 1) for _ in range(random.randint(0, 2))])
    if r < 0.55:
        return D(*[(S(random.choice(STRS)), expr(depth + 1)) for _ in range(random.randint(0, 2))])
    if r < 0.8:
        fn = random.choice([G(*random.choice(SAFE_CALLABLES)), G(*random.choice(CANARY_GLOBALS)), expr(depth + 1)])
        return CALL(fn, *[expr(depth + 1) for _ in range(random.randint(0, 2))])
    if r < 0.85:
        return NEWOBJ(G(*random.choice(SAFE_CALLABLES + CANARY_GLOBALS)), *[expr(depth + 1) for _ in range(random.randint(0, 2))])
    if r < 0.9:
        return OBJ(expr(depth + 1), *[expr(depth + 1) for _ in range(random.randint(0, 1))])
    if r < 0.95:
        return BUILD(expr(depth + 1), expr(depth + 1))
    return CALLRAW(G(*random.choice(CANARY_GLOBALS)), L(S("x")))


RUNNER = r'''
import io, pickle, sys, threading
sys.path.insert(0, "/tmp/work/canary")
import cmod
data = open(sys.argv[1], "rb").read()
f = io.BytesIO(data)
while f.tell() < len(data):
    try:
        pickle.load(f)
    except BaseException as exc:
        break
for t in threading.enumerate():
    if t is not threading.main_thread():
        t.join(1)
'''

mismatches = 0
ran = 0
t0 = time.time()
for i in range(N):
    e = L(*[expr() for _ in range(random.randint(1, 3))])
    try:
        data = build(e, random.choice(PROTO))
    except Exception:
        continue
    path = "/tmp/work/df_case.pkl"
    open(path, "wb").write(data)
    try:
        proc = subprocess.run([sys.executable, "-I", "-c", RUNNER, path], capture_output=True, text=True, timeout=10)
        real = "HIT" in proc.stdout
    except subprocess.TimeoutExpired:
        continue
    ctx = Context(time.monotonic() + 10)
    try:
        loaders.scan_blob(ctx, data, "d", "d.pkl", 0, top=True)
    except ScanAbort as exc:
        ctx.report("unsupported", "d", str(exc))
    mine = any(f.kind != "unsupported" for f in ctx.findings)
    ran += 1
    if mine != real:
        mismatches += 1
        keep = f"/tmp/work/dfmis_{mismatches}.pkl"
        open(keep, "wb").write(data)
        print(f"MISMATCH real={real} scanner={mine} -> {keep}", [(f.kind, f.detail[:100]) for f in ctx.findings][:3],
              proc.stdout.strip()[:200], flush=True)
print(f"ran {ran} cases in {time.time() - t0:.0f}s, mismatches {mismatches}")

